item.command:
"<USER_HOME>\\.cache\\codex-runtimes\\codex-primary-runtime\\dependencies\\native\\powershell\\pwsh.exe" -NoProfile -Command '$ErrorActionPreference = '"'Stop'
"'$taskRoot = '"'D:\\tx-harness-participants\\coverage-attempt01\\pilot-codex-T03-r1'
"'$utf8 = [System.Text.UTF8Encoding]::new($false, $true)
$names = @('"'announcement.md','catalog.json','contacts.csv','protected.txt')
"'$original = @{}
foreach ($name in $names) { $original[$name] = [System.IO.File]::ReadAllBytes("$taskRoot'"\\inputs\\"'$name") }
$a = $utf8.GetString($original['"'announcement.md'])
"'$j = $utf8.GetString($original['"'catalog.json'])
"'$c = $utf8.GetString($original['"'contacts.csv'])
"'$aPattern = '"'(?m)"'^(正式发布：)2026-10-20 10:00(?='"\\r?"'$)'"'
"'$jPattern = '"'(\"id\"\\s*:\\s*\"P-A\"["'^{}]*"price_cents"'"\\s*:\\s*)119900\\b'
"'$cPattern = '"'(?m)"'^(support,)support@example'"\\.test(,)'
foreach ("'$item in @(@($a,$aPattern),@($j,$jPattern),@($c,$cPattern))) { if ([regex]::Matches($item[0],$item[1]).Count -ne 1) { throw '"'Expected exactly one target match' } }
"'$aNew = [regex]::Replace($a,$aPattern,'"'"'${1}2026-10-22 14:30'"')
"'$jNew = [regex]::Replace($j,$jPattern,'"'"'${1}129900'"')
"'$cNew = [regex]::Replace($c,$cPattern,'"'"'${1}help@example.test${2}'"')
"'$parsed = $jNew | ConvertFrom-Json
if ($parsed.products[0].id -ne '"'P-A' -or "'$parsed.products[0].price_cents -ne 129900) { throw '"'Product validation failed' }
[System.IO.Directory]::CreateDirectory(\""'$taskRoot'"\\outputs\\bundle\") | Out-Null
"'$expected = @{'"'announcement.md'="'$utf8.GetBytes($aNew); '"'catalog.json'="'$utf8.GetBytes($jNew); '"'contacts.csv'="'$utf8.GetBytes($cNew); '"'protected.txt'="'$original['"'protected.txt']}
foreach ("'$name in $names) { [System.IO.File]::WriteAllBytes("$taskRoot'"\\outputs\\bundle\\"'$name", $expected[$name]) }
$log = [ordered]@{ changes = @([ordered]@{path='"'announcement.md';field='release_time';old='2026-10-20 10:00';new='2026-10-22 14:30'},[ordered]@{path='catalog.json';field='products[P-A].price_cents';old=119900;new=129900},[ordered]@{path='contacts.csv';field='support.email';old='support@example.test';new='help@example.test'}); unchanged_paths = @('protected.txt') }
[System.IO.File]::WriteAllText(\""'$taskRoot'"\\outputs\\change_log.json\", ("'$log | ConvertTo-Json -Depth 5), $utf8)
foreach ($name in $names) {
 $actual = [System.IO.File]::ReadAllBytes("$taskRoot'"\\outputs\\bundle\\"'$name")
 if ([Convert]::ToBase64String($actual) -cne [Convert]::ToBase64String($expected[$name])) { throw "Output bytes mismatch: $name" }
 $inputNow = [System.IO.File]::ReadAllBytes("$taskRoot'"\\inputs\\"'$name")
 if ([Convert]::ToBase64String($inputNow) -cne [Convert]::ToBase64String($original[$name])) { throw "Input modified: $name" }
 [Console]::WriteLine("Verified: $name ($($actual.Length) bytes)")
}
$logRead = [System.IO.File]::ReadAllText("$taskRoot'"\\outputs\\change_log.json\") | ConvertFrom-Json
if ("'$logRead.changes.Count -ne 3 -or $logRead.unchanged_paths[0] -ne '"'protected.txt') { throw 'Log validation failed' }
[Console]::WriteLine('Verified: change_log.json; all input files unchanged; only authorized replacements applied.')"
